consumedContracts.interfaceSketch:
interface ToolHook { id: string; toolId: string; run(ctx: ToolHookContext): Promise<void> }
interface ToolHookContext { toolId: string; input: unknown; result: ToolResult; caller: 'agent' | 'daemon' | 'workflow' }
interface HookFailure { hookId: string; message: string }
interface ToolResultHookReport { hookFailures?: HookFailure[] }
registerToolHook(hook: ToolHook): void

interface OutputSchemaField<O> { outputSchema?: JsonSchema; readonly outputType?: O }
type ToolOutput<T> = T extends OutputSchemaField<infer O> ? O : unknown
interface TypedToolResult<O> { success: boolean; data?: O; error?: ToolFailure }
callTool<T extends OutputSchemaField<any> & { id: string }>(tool: T, input: ToolInput<T>, deps: ToolDeps): Promise<TypedToolResult<ToolOutput<T>>>
  // + outputSchema is a typebox TSchema; TypedTool; callTool signature: outputSchema?: TSchema (typebox); TypedTool = Tool & { inputSchema: TSchema; outputSchema: TSchema }; callTool<T extends TypedTool>(tool: T, input: Static<T['inputSchema']>, deps: ToolDeps): Promise<TypedToolResult<Static<T['outputSchema']>>>;  // Refines the sc2 sketch as approved in the s2 LLD (requirement R2): typebox instead of JsonSchema plus a phantom type, and a typed input. (amend:AMD-b7a68147dcf72034-6)
  // + family tools are checked at run time and typed for callTool as TSchema: A tool built from an op table (defineGhFamily, defineJiraFamily) returns GhFamilyTool = TypedTool & { ops }, whose inputSchema and outputSchema are TSchema, so callTool<T>'s Static<T['inputSchema']> and Static<T['outputSchema']> are not concrete per family; the shapes are enforced at run time by the executor's input check before execute and its output check after execute (failed('schema-mismatch') when the declared output gets no data or data outside the union);  // Records the level of typing the op-table family tools actually give: run-time-checked shapes, no concrete per-family compile-time types. A concrete per-family type is left to a later Story. (amend:AMD-b7a68147dcf72034-10)

type ApprovalClass = 'none' | 'common' | 'destructive'
interface ApprovalField<I> { approval?: ApprovalClass | ((input: I) => ApprovalClass) }
type CommonApprovalMode = 'auto' | 'ask'
interface ApprovalRequest { requestId: string; toolId: string; approvalClass: 'common' | 'destructive'; inputSummary: string; reason: string; expiresAt: string }
interface ApprovalAnswer { requestId: string; decision: 'approve' | 'decline' }
type ApprovalDenial = 'declined' | 'timed-out' | 'no-client'
interface ApprovalGate { ask(req: ApprovalRequest): Promise<ApprovalAnswer | ApprovalDenial> }
// IPC methods: approval.request (daemon to client), approval.answer (client to daemon)
  // + ApprovalRequest repoPath, arguments, preview; CommonApprovalMode; approval.subscribe: ApprovalRequest gains repoPath: string, arguments: Record<string, unknown> and preview?: { title: string; content: string }; CommonApprovalMode = 'manual' | 'edit-auto' | 'auto'; ApprovalDenial gains 'cancelled'; IPC method approval.request (daemon to client) is realised as approval.subscribe (a client-opened stream carrying 'gate' frames) plus approval.answer;  // The request must name the repository and the exact arguments (DEF S003 FR001), the chat has three modes, and the daemon can push only over a stream the client opened. Additive refinements of a contract only s3 owns. (amend:AMD-b7a68147dcf72034-4)

type ToolFailureKind = 'missing-tool' | 'missing-signin' | 'unreachable' | 'timed-out' | 'rejected' | 'conversion-failed' | 'schema-mismatch' | 'denied'
interface ToolFailure { kind: ToolFailureKind; message: string; denial?: ApprovalDenial }
  // + ToolResult.failure, ToolFailure.original and ToolDenialReason?: ToolResult.failure?: ToolFailure; ToolFailure.original?: string (the tool's raw output, truncated, kept for diagnosis); type ToolDenialReason = 'declined' | 'timed-out' | 'no-client', which ToolFailure.denial uses in place of the ApprovalDenial type from sc4;  // The Story's second functional requirement says a conversion that fails the check is reported as the tool's failure with the original output available for diagnosis, and the executor has to carry a typed failure on the ToolResult that agents and code both receive. sc5's sketch types denial with ApprovalDenial, owned by s3 (sc4), but s2 has no dependency on s3 in the Epic graph and so cannot compile against it; declaring the three-value union in sc5 removes the dependency, and s3 reuses it. All three additions are optional or additive; a caller that ignores them sees today's success, output and error fields. (amend:AMD-b7a68147dcf72034-3)
  // + ToolDenialReason 'cancelled': type ToolDenialReason = 'declined' | 'timed-out' | 'no-client' | 'cancelled' (an approval aborted by the caller's signal);  // An aborted approval needs a reason distinct from a decline or a timeout; s2 owns the type and s3 raises the value. (amend:AMD-b7a68147dcf72034-5)
